const TOTAL_STEPS = 100;
const step = (context.get("iveEmulatorStep") || 0) % TOTAL_STEPS;
const values = new Array(tagNames.length).fill(0);

// Номер тега здесь такой же, как в PDF: 1..125.
function set(tagNumber, value) {
    values[tagNumber - 1] = round(value);
}

function round(value) {
    return Number(value.toFixed(3));
}

function wave(period, shift) {
    return Math.sin((2 * Math.PI * (step + (shift || 0))) / period);
}

function limit(value, min, max) {
    return Math.min(max, Math.max(min, value));
}

function makeLevels(count) {
    const levels = [];
    for (let i = 0; i < count; i += 1) {
        levels.push(165 + i * 2.4 + 1.8 * wave(40 + i * 3, i) - step * 0.018);
    }
    return levels;
}

function makeVolumes(levels) {
    return levels.map((level, i) => level * (0.34 + i * 0.004));
}

// Сценарий 100 секунд: бурение, затем снижение насосов, затем соединение.
const phase = {
    drilling: step < 72,
    pumpsRunning: step < 78,
    connection: step >= 86
};

const drilling = {
    wob: phase.drilling ? 13 + 2.2 * wave(31) + 0.8 * wave(9) : limit(7 - (step - 72) * 0.6, 0, 7),
    rop: 0,
    holeDepth: 3150 + Math.min(step, 72) * 0.055,
    offBottom: phase.drilling ? 0.35 + 0.08 * wave(20) : 1.5 + Math.max(0, step - 72) * 0.18,
    tripSpeed: phase.drilling ? -0.03 + 0.01 * wave(15) : (phase.connection ? 0 : 0.16 + 0.03 * wave(10)),
    standFeed: (step % 30) * 0.32
};
drilling.rop = phase.drilling ? 26 + 5 * wave(37, 5) - 0.28 * drilling.wob : 0;
drilling.bitDepth = drilling.holeDepth - drilling.offBottom;
drilling.standsDown = Math.floor(drilling.bitDepth / 27);

const rotation = {
    rotaryRpm: phase.drilling ? 58 + 5 * wave(22, 4) : 0,
    topDriveRpm: phase.drilling ? 118 + 8 * wave(18) : (phase.connection ? 0 : 42 + 6 * wave(12))
};
rotation.rotaryTorque = phase.drilling ? 7 + drilling.wob * 0.75 + rotation.rotaryRpm * 0.035 + 1.5 * wave(13) : 0;
rotation.topDriveTorque = phase.drilling ? 18 + drilling.wob * 1.25 + 1.7 * wave(15, 2) : 0;

const pumpFactor = phase.pumpsRunning ? 1 : limit(1 - (step - 78) * 0.045, 0.25, 1);
const pumps = {
    pump1: pumpFactor * (92 + 4 * wave(18)),
    pump2: pumpFactor * (88 + 3 * wave(21, 3)),
    pump3: pumpFactor * (72 + 2 * wave(25, 5))
};
pumps.sum = pumps.pump1 + pumps.pump2 + pumps.pump3;
pumps.flow1 = pumps.pump1 * 0.18;
pumps.flow2 = pumps.pump2 * 0.18;
pumps.flow3 = pumps.pump3 * 0.18;
pumps.flowIn = pumps.flow1 + pumps.flow2 + pumps.flow3;
pumps.flowOut = pumps.flowIn * (0.94 + 0.018 * wave(28, 6));
pumps.flowOutPct = limit((pumps.flowOut / 55) * 100, 0, 100);
pumps.flowChangePct = 1.8 * wave(24, 3) + (step > 78 ? -2.5 : 0);
pumps.pressure = pumpFactor * (8.5 + pumps.sum * 0.035 + drilling.wob * 0.25) + 0.35 * wave(17);

const hook = {
    position: 24 - step * 0.045 + 0.25 * wave(16),
    weight: 205 - drilling.wob + 2.5 * wave(19) - (phase.connection ? 22 : 0)
};

const gasPeak = Math.max(0, 1 - Math.abs(step - 48) / 18);
const gas = {
    mouthNkpr: 0.6 + gasPeak * 4.8 + 0.2 * wave(12),
    mouthH2s: 1.2 + gasPeak * 6.2,
    underRotorH2s: 0.9 + gasPeak * 4.5,
    floorH2s: 0.8 + gasPeak * 3.8,
    cleaningH2s: 0.7 + gasPeak * 2.4,
    underRotorNkpr: 0.5 + gasPeak * 3.5,
    floorNkpr: 0.4 + gasPeak * 2.8
};

const mud = {
    densityBase: 1.21 + 0.015 * wave(80),
    tempIn: 31 + 0.8 * wave(70, 8),
    tempOut: 44 + 1.5 * wave(55)
};

const tanks = {
    levels: makeLevels(14)
};
tanks.volumes = makeVolumes(tanks.levels);
tanks.totalVolume = tanks.volumes.slice(0, 8).reduce((sum, value) => sum + value, 0);
tanks.deltaVolume = tanks.totalVolume - 495.744;

const connection = {
    slips: phase.connection ? 1 : 0,
    machineKeyTorque: phase.connection ? 34 + 8 * wave(10) : 0,
    hydraulicKeyTorque: phase.connection ? 1150 + 220 * wave(8) : 0,
    akbTorque: phase.connection ? 18 + 3 * wave(9) : 0,
    keyPressure: phase.connection ? 8.5 + 1.2 * wave(7) : 0.4,
    highLowSpeed: phase.connection ? 1 : 0,
    section1: phase.connection && step % 12 < 6 ? 1 : 0,
    section2: phase.connection && step % 12 >= 6 ? 1 : 0
};

const staticValues = {
    hookWeight2: 0,
    flowIn1: 0,
    manifoldPressure2: 0,
    casingKey1: 0,
    casingKey2: 0,
    dispersionPressure: 0,
    dispersionPumpStrokes: 0,
    dispersionPumpFlow: 0
};

// Ниже основной блок для расширения: меняем или добавляем set(номер_тега, значение).
set(1, hook.weight);
set(2, hook.position);
set(3, pumps.pressure);
set(4, connection.hydraulicKeyTorque);
set(5, staticValues.hookWeight2);
set(6, pumps.flowOutPct);
set(7, gas.mouthNkpr);
set(8, gas.mouthH2s);
set(9, gas.underRotorH2s);
set(10, gas.floorH2s);
set(11, mud.tempOut);
set(12, staticValues.flowIn1);
set(13, connection.akbTorque);
set(14, rotation.rotaryTorque);
set(15, rotation.rotaryRpm);
set(16, staticValues.manifoldPressure2);
set(17, connection.machineKeyTorque);
set(18, mud.tempIn);
set(19, gas.cleaningH2s);

for (let i = 0; i < 6; i += 1) set(20 + i, mud.densityBase + i * 0.006 + 0.002 * wave(30, i));
for (let i = 0; i < 6; i += 1) set(26 + i, tanks.levels[i]);
for (let i = 0; i < 6; i += 1) set(32 + i, tanks.volumes[i]);

set(38, tanks.totalVolume);
set(39, drilling.wob);
set(40, drilling.rop);
set(41, drilling.tripSpeed);
set(42, drilling.bitDepth);
set(43, drilling.holeDepth);
set(44, pumps.flowChangePct);
set(45, drilling.standFeed);
set(46, drilling.standsDown);
set(47, pumps.flowIn);
set(48, connection.slips);
set(49, gas.underRotorNkpr);
set(50, tanks.levels[6]);
set(51, tanks.volumes[6]);
set(52, rotation.topDriveRpm);
set(53, rotation.topDriveTorque);
set(54, tanks.levels[7]);
set(55, tanks.volumes[7]);
set(56, pumps.pump1);
set(57, pumps.pump2);
set(58, pumps.sum);
set(59, gas.floorNkpr);
set(60, pumps.pump3);

for (let i = 8; i < 14; i += 1) {
    const tag = 61 + (i - 8) * 2;
    set(tag, tanks.levels[i]);
    set(tag + 1, tanks.volumes[i]);
}

set(73, tanks.deltaVolume);
set(74, staticValues.casingKey1);
set(75, staticValues.casingKey2);
set(76, connection.keyPressure);
set(77, connection.highLowSpeed);
set(78, connection.section1);
set(79, connection.section2);
set(80, 1);

for (let i = 0; i < 5; i += 1) set(81 + i, 0.35 + gasPeak * (2.4 - i * 0.2) + 0.05 * wave(11 + i, i));
for (let i = 0; i < 4; i += 1) set(86 + i, 0);
set(90, 0);
set(91, 0);
for (let i = 0; i < 10; i += 1) set(92 + i, 0.12 + gasPeak * (1.4 - i * 0.06));

set(102, 0);
for (let i = 0; i < 4; i += 1) set(103 + i, mud.densityBase + 0.012 + i * 0.004);
set(107, drilling.offBottom);
set(108, staticValues.dispersionPressure);
set(109, staticValues.dispersionPumpStrokes);
set(110, staticValues.dispersionPumpFlow);
set(111, pumps.flow1);
set(112, pumps.flow2);
set(113, 184.5 + step / 3600);
set(114, phase.connection ? (step - 86) * 0.18 : 0);
set(115, pumps.pressure * 0.96);
set(116, pumps.pressure * 0.93);
set(117, drilling.rop > 0 ? 1 / drilling.rop : 0);
set(118, 0.16 + gasPeak * 1.1);
set(119, 0.14 + gasPeak * 0.9);
set(120, 0.12 + gasPeak * 0.8);
set(121, pumps.flow3);
set(122, pumps.pressure * 0.9);
set(123, 0.65 + gasPeak * 2.2);
set(124, 0.55 + gasPeak * 1.9);
set(125, 0.45 + gasPeak * 1.5);

msg.payload = values;
msg.tagNames = tagNames;
msg.iteration = step + 1;
msg.scenarioLength = TOTAL_STEPS;
msg.emulator = "ИВЭ Modbus-Read drilling state";

context.set("iveEmulatorStep", (step + 1) % TOTAL_STEPS);
node.status({ fill: "green", shape: "dot", text: msg.iteration + "/" + TOTAL_STEPS + ", " + values.length + " tags" });
return msg;

msg.payload = '-hide_banner -loglevel error -rtsp_transport tcp ' +
    '-i "rtsp://127.0.0.1:8554/webcam" ' +
    '-an -c copy -f mpegts pipe:1';
return msg;

if (Buffer.isBuffer(msg.payload)) {
    msg.chunkLength = msg.payload.length;
    msg.payload = {
        chunkLength: msg.chunkLength,
        headHex: msg.payload.subarray(0, Math.min(32, msg.payload.length)).toString('hex')
    };
}
return msg;

if (msg.status && msg.status.text) {
    const m = msg.status.text.match(/^pid:(\d+)/);
    if (m) {
        flow.set("ffmpeg-pid", Number(m[1]));
    }
}
return null;

const pid = flow.get("ffmpeg-pid");
if (!pid) {
    node.warn("ffmpeg-pid not set, skip taskkill");
    return null;
}
msg.pid = pid;
msg.payload = `/PID ${pid}`;
return msg;
